const esc = t => String(t ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const num = n => (n === null || n === undefined || n === '') ? '–' : Number(n).toLocaleString('en-US');
const BRAND = { violet: '#7B2FF7', orange: '#FF7A1A', ink: '#1d1530', muted: '#6b6480', line: '#ece8f3' };
const shell = (title, subtitle, body, footer) => `<!doctype html><html><body style="margin:0;background:#f6f4fa;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:${BRAND.ink}">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="640" cellpadding="0" cellspacing="0" style="max-width:640px;background:#fff;border-radius:14px;overflow:hidden">
<tr><td style="background:linear-gradient(90deg,${BRAND.violet},${BRAND.orange});background-color:${BRAND.violet};padding:22px 26px;color:#fff">
<div style="font-size:12px;letter-spacing:.12em;text-transform:uppercase;opacity:.85">${esc(subtitle)}</div>
<div style="font-size:22px;font-weight:700;margin-top:4px">${esc(title)}</div></td></tr>
<tr><td style="padding:22px 26px">${body}</td></tr>
<tr><td style="padding:14px 26px;border-top:1px solid ${BRAND.line};font-size:12px;color:${BRAND.muted}">${footer || ''}</td></tr>
</table></td></tr></table></body></html>`;
const stat = (label, value) => `<td style="padding:10px 12px;background:#faf8fd;border-radius:10px;text-align:center"><div style="font-size:20px;font-weight:700">${value}</div><div style="font-size:11px;color:${BRAND.muted};text-transform:uppercase;letter-spacing:.06em">${esc(label)}</div></td>`;
const stats = arr => `<table role="presentation" width="100%" cellspacing="6" cellpadding="0" style="margin:0 0 14px"><tr>${arr.map(([l,v]) => stat(l,v)).join('')}</tr></table>`;

const s = $('Settings').first().json;
const run = $('Wait for run').last().json.data;
const rows = $input.all().map(i => i.json).filter(r => r && r.url);
const changedAll = rows.filter(r => r.changed === true).sort((a, b) => (b.changePct || 0) - (a.changePct || 0));
// Noise learning: many pages shift a little on every load (carousels, counters, ads, layout shifts).
// We keep the last 5 change values per page (workflow static data, saved on scheduled runs) and, once 3 exist,
// only alert when a change is clearly above what the page usually does.
const memo = $getWorkflowStaticData('global');
memo.hist = memo.hist || {};
const median = a => { const b = [...a].sort((x, y) => x - y); const m = Math.floor(b.length / 2); return b.length % 2 ? b[m] : (b[m - 1] + b[m]) / 2; };
const ignored = [];
const changed = [];
for (const r of changedAll) {
  const k = `${r.url}|${r.device}`;
  const prior = memo.hist[k] || [];
  r.typicalPct = prior.length ? Math.round(10 * median(prior)) / 10 : null;
  if (s.suppressNoise !== false && prior.length >= 3 && r.changePct <= Math.max(1.5 * r.typicalPct, r.typicalPct + 2)) ignored.push(r); else changed.push(r);
}
if (run.status === 'SUCCEEDED') for (const r of changedAll) { const k = `${r.url}|${r.device}`; memo.hist[k] = [...(memo.hist[k] || []), Number(r.changePct)].slice(-5); }
const baseline = rows.filter(r => !r.errorCode && (r.changed === null || r.changed === undefined));
const errors = rows.filter(r => r.errorCode);
const ago = d => { if (!d) return 'the last check'; const m = Math.round((Date.now() - new Date(d).getTime()) / 6e4); return m < 90 ? `the check ${m} min ago` : m < 2880 ? `the check ${Math.round(m / 60)} h ago` : `the check ${Math.round(m / 1440)} days ago`; };
const host = u => String(u).replace(/^https?:\/\//, '').replace(/\/$/, '');
let body = stats([['changed', changed.length], ['first capture', baseline.length], ['errors', errors.length]]);
for (const r of changed) {
  body += `<div style="margin:16px 0 22px">
  <div style="font-size:15px;font-weight:700">${esc(r.title || host(r.url))}</div>
  <div style="font-size:12px;color:${BRAND.muted};margin:2px 0 8px"><a href="${esc(r.finalUrl || r.url)}" style="color:${BRAND.violet}">${esc(host(r.finalUrl || r.url))}</a> · ${esc(r.device)} · <b style="color:#b42318">${r.changePct}% of the page changed</b> since ${esc(ago(r.previousCapturedAt))}${r.typicalPct !== null ? ` (typical: ${r.typicalPct}%)` : ''}</div>
  ${r.diffImageUrl ? `<a href="${esc(r.diffImageUrl)}"><img src="${esc(r.diffImageUrl)}" width="588" alt="Changes highlighted in red" style="width:100%;max-width:588px;height:auto;border:1px solid ${BRAND.line};border-radius:8px"></a>` : ''}
  <div style="font-size:12px;margin-top:6px"><a href="${esc(r.screenshotUrl)}" style="color:${BRAND.orange}">Current screenshot</a>${r.diffImageUrl ? ` · <a href="${esc(r.diffImageUrl)}" style="color:${BRAND.orange}">Diff (red = changed)</a>` : ''}</div></div>`;
}
if (ignored.length) body += `<p style="font-size:12px;color:${BRAND.muted};margin:10px 0">Usual noise, not alerted: ${ignored.map(r => `${esc(host(r.url))} (${r.changePct}%, typical ${r.typicalPct}%)`).join(', ')}</p>`;
if (baseline.length) body += `<h3 style="font-size:15px;margin:18px 0 6px">Now watching</h3><p style="font-size:12px;color:${BRAND.muted};margin:0 0 6px">First capture saved as the reference. From the next run on you only hear about these pages when they change by at least ${esc(s.changeThresholdPct)}%.</p>` +
  baseline.map(r => `<div style="font-size:13px;padding:3px 0">✓ <a href="${esc(r.screenshotUrl)}" style="color:${BRAND.violet}">${esc(r.title || host(r.url))}</a> <span style="color:${BRAND.muted}">(${esc(host(r.url))}, ${esc(r.device)})</span></div>`).join('');
if (errors.length) body += `<h3 style="font-size:15px;margin:18px 0 6px;color:#b42318">Could not capture</h3>` + errors.map(r => `<div style="font-size:12px">⚠ ${esc(host(r.url))} (${esc(r.device)}): ${esc(r.errorMessage || r.errorCode)}</div>`).join('');
if (run.status !== 'SUCCEEDED') body += `<p style="font-size:12px;color:#b42318">⚠ The Apify run ended with status ${esc(run.status)}.</p>`;
const subject = changed.length ? `${changed.length} page${changed.length === 1 ? '' : 's'} changed: ${changed.slice(0, 2).map(r => host(r.url)).join(', ')}${changed.length > 2 ? ' …' : ''}`
  : (baseline.length ? `Website monitor is live: ${baseline.length} page${baseline.length === 1 ? '' : 's'} saved as reference` : `Website monitor: ${errors.length} page(s) could not be captured`);
const html = shell(subject, 'Website Change Monitor · ' + new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC', body,
  'Free template by pegton · screenshots by pegton/website-screenshot-monitor on Apify. More templates: <a href="https://pegton.gumroad.com" style="color:' + BRAND.violet + '">pegton.gumroad.com</a>');
const slackText = `*${subject}*\n` + changed.map(r => `• <${r.finalUrl || r.url}|${host(r.url)}> (${r.device}): ${r.changePct}% changed · <${r.diffImageUrl}|diff>`).join('\n');
return [{ json: { subject, html, slackText, reportCount: changed.length + baseline.length + errors.length, changed: changed.length, runStatus: run.status } }];
